			/**
			 * @param {any} val
			 */
			function setRcptSeCd(val){
			    
			    var cmbVal = app.lookup("cmb1");
			    var grpLotForm = app.lookup("grpRqstRcptResult1").getLayout();
			    var ipb1 = app.lookup("ipb1");
			    var cmb1 = app.lookup("cmb_YNGBGS_STTS_LCLAS_SE_CD");
			    
			    
			    if('21' == val){
			        
			        app.lookup("opt_PRCS_YMD").value = '접수일자';
			        
			        grpLotForm.setRowVisible(2, false);
			        grpLotForm.setRowVisible(3, true);
			        ipb1.userAttr("required", "N");
			        cmb1.userAttr("required", "Y");
			        
			    }else if('30' == val){
			        
			        app.lookup("opt_PRCS_YMD").value = '반려일자';
			        
			        grpLotForm.setRowVisible(2, true);
			        grpLotForm.setRowVisible(3, false);
			        ipb1.userAttr("required", "Y");
			        cmb1.userAttr("required", "N");
			        
			    }
			    
			        app.lookup("dsCAA100").setValue(0, "RJCT_CS_CN"  , null);
			        
			        app.lookup("dsCAA100").setValue(0, "PROBM_STTS_LCLAS_SE_CD"  , null);
			        app.lookup("dsCAA100").setValue(0, "PROBM_STTS_MLSFC_SE_CD"  , null);
			        app.lookup("dsCAA100").setValue(0, "PROBM_STTS_SCLAS_SE_CD"  , null);
			        app.lookup("dsCAA100").setValue(0, "PROBM_CAS_LCLAS_SE_CD"   , null);
			        app.lookup("dsCAA100").setValue(0, "PROBM_CAS_SCLAS_SE_CD"   , null);
			        app.lookup("dsCAA100").setValue(0, "PROBM_CAS_ETC_CN"        , null);
			        app.lookup("dsCAA100").setValue(0, "YNGBGS_STTS_LCLAS_SE_CD" , null);       
			}

